   208	static exr_result_t
   209	attr_destroy (exr_context_t ctxt, exr_attribute_t* attr)
   210	{
   211	    exr_result_t rv = EXR_ERR_SUCCESS;
   212	    switch (attr->type)
   213	    {
   214	        case EXR_ATTR_CHLIST:
   215	            rv = exr_attr_chlist_destroy (ctxt, attr->chlist);
   216	            break;
   217	        case EXR_ATTR_FLOAT_VECTOR:
   218	            rv = exr_attr_float_vector_destroy (ctxt, attr->floatvector);
   219	            break;
   220	        case EXR_ATTR_PREVIEW:
   221	            rv = exr_attr_preview_destroy (ctxt, attr->preview);
   222	            break;
   223	        case EXR_ATTR_STRING:
   224	            rv = exr_attr_string_destroy (ctxt, attr->string);
   225	            break;
   226	        case EXR_ATTR_STRING_VECTOR:
   227	            rv = exr_attr_string_vector_destroy (ctxt, attr->stringvector);
   228	            break;
   229	        case EXR_ATTR_OPAQUE:
   230	            rv = exr_attr_opaquedata_destroy (ctxt, attr->opaque);
   231	            break;
   232	        case EXR_ATTR_BOX2I:
   233	        case EXR_ATTR_BOX2F:
   234	        case EXR_ATTR_CHROMATICITIES:
   235	        case EXR_ATTR_COMPRESSION:
   236	        case EXR_ATTR_ENVMAP:
   237	        case EXR_ATTR_LINEORDER:
   238	        case EXR_ATTR_DOUBLE:
   239	        case EXR_ATTR_FLOAT:
   240	        case EXR_ATTR_INT:
   241	        case EXR_ATTR_KEYCODE:
   242	        case EXR_ATTR_M33F:
   243	        case EXR_ATTR_M33D:
   244	        case EXR_ATTR_M44F:
   245	        case EXR_ATTR_M44D:
   246	        case EXR_ATTR_RATIONAL:
   247	        case EXR_ATTR_TILEDESC:
   248	        case EXR_ATTR_TIMECODE:
   249	        case EXR_ATTR_V2I:
   250	        case EXR_ATTR_V2F:
   251	        case EXR_ATTR_V2D:
   252	        case EXR_ATTR_V3I:
   253	        case EXR_ATTR_V3F:
   254	        case EXR_ATTR_V3D:
   255	        case EXR_ATTR_DEEP_IMAGE_STATE:
   256	        case EXR_ATTR_UNKNOWN:
   257	        case EXR_ATTR_LAST_KNOWN_TYPE:
   258	        default: break;
   259	    }
   260	    /* we don't care about the string because they were built into the
   261	     * allocation block of the attribute as necessary */
   262	    ctxt->free_fn (attr);
   263	    return rv;
   264	}
